# ===========================================================================
# 11. Aggregates + convenience accessors
# ===========================================================================
ALL_MAIN_TABLES = GROUP1_TABLES + GROUP2_TABLES
ALL_DEPENDENCY_TABLES = LAYER1_TABLES + LAYER2_TABLES
ALL_TABLES = ALL_MAIN_TABLES + ALL_DEPENDENCY_TABLES

DATA_OBJECTS = ALL_MAIN_TABLES + LAYER1_TABLES + LAYER2_TABLES


def iter_main_rows():
    """Yield ``(table, row)`` for every Group 1/Group 2 main-table row."""
    for table in ALL_MAIN_TABLES:
        for row in table["rows"]:
            yield table, row


def iter_layer1_rows():
    """Yield ``(table, row)`` for every Layer-1 dependency row."""
    for table in LAYER1_TABLES:
        for row in table["rows"]:
            yield table, row


def iter_layer2_rows():
    """Yield ``(table, row)`` for every Layer-2 dependency row."""
    for table in LAYER2_TABLES:
        for row in table["rows"]:
            yield table, row


def main_row_count():
    """Total number of main (Group 1 + Group 2) rows (expected: 94)."""
    return sum(len(t["rows"]) for t in ALL_MAIN_TABLES)


def evidence_row_count():
    """Main + Layer-1 + Layer-2 rows (expected: 282)."""
    return (sum(len(t["rows"]) for t in ALL_MAIN_TABLES)
            + sum(len(t["rows"]) for t in LAYER1_TABLES)
            + sum(len(t["rows"]) for t in LAYER2_TABLES))


def _iter_all_text():
    """Yield every free-text string across the audit corpus (for flag counts)."""
    for table in ALL_MAIN_TABLES:
        for row in table["rows"]:
            for value in row.values():
                if isinstance(value, str):
                    yield value
    for table in LAYER2_TABLES:
        for row in table["rows"]:
            yield row["notes"]
    yield LEGEND_NOTES_FLAGS
    for item in COVERAGE_REGISTER["items"]:
        for value in item.values():
            if isinstance(value, str):
                yield value


def count_flag(token):
    """Count document-wide occurrences of an audit-discipline flag token."""
    return sum(text.count(token) for text in _iter_all_text())


def all_flag_counts():
    """Return ``{token: count}`` for every flag in :data:`FLAG_TOKENS`."""
    return {token: count_flag(token) for token in FLAG_TOKENS}


def new_service_location_for(provenance):
    """Return the new service location for a provenance token, or ``None``."""
    return NEW_SERVICE_LOCATION_BY_PROVENANCE.get(provenance)
